mapper.select:
SELECT id, name, description, images, brand, category_id AS categoryId,
       merchant_id AS merchantId, status, sales,
       created_at AS createdAt, updated_at AS updatedAt
FROM product
WHERE merchant_id = #{merchantId}

    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM product
WHERE merchant_id = #{merchantId}

    AND status = #{status}

SELECT DISTINCT o.id
FROM `order` o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId}
WHERE o.status IN (2, 3, 4, 5, 6, 7)

    AND o.status = #{status}

ORDER BY o.created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(DISTINCT o.id)
FROM `order` o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId}
WHERE o.status IN (2, 3, 4, 5, 6, 7)

    AND o.status = #{status}

SELECT COALESCE(SUM(oi.subtotal), 0)
FROM `order` o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId}
WHERE o.status IN (2, 3, 4)

    AND DATE(o.created_at) >= #{startDate}


    AND DATE(o.created_at) <= #{endDate}

SELECT COUNT(DISTINCT o.id)
FROM `order` o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId}
WHERE o.status IN (2, 3, 4)

    AND DATE(o.created_at) >= #{startDate}


    AND DATE(o.created_at) <= #{endDate}

SELECT oi.product_id AS productId,
       p.name AS productName,
       SUM(oi.quantity) AS salesCount,
       SUM(oi.subtotal) AS totalAmount
FROM `order` o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId}
WHERE o.status IN (2, 3, 4)

    AND DATE(o.created_at) >= #{startDate}


    AND DATE(o.created_at) <= #{endDate}

GROUP BY oi.product_id, p.name
ORDER BY totalAmount DESC
LIMIT #{limit}

SELECT p.category_id AS categoryId, c.name AS categoryName, SUM(oi.subtotal) AS totalAmount FROM `order` o INNER JOIN order_item oi ON oi.order_id = o.id INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId} LEFT JOIN category c ON c.id = p.category_id WHERE o.status IN (2, 3, 4)
AND DATE(o.created_at) >= #{startDate}
AND DATE(o.created_at) <= #{endDate}
GROUP BY p.category_id, c.name ORDER BY totalAmount DESC

SELECT DATE(o.created_at) AS date,
       SUM(oi.subtotal) AS amount
FROM `order` o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product p ON p.id = oi.product_id AND p.merchant_id = #{merchantId}
WHERE o.status IN (2, 3, 4)

    AND DATE(o.created_at) >= #{startDate}


    AND DATE(o.created_at) <= #{endDate}

GROUP BY DATE(o.created_at)
ORDER BY date ASC
